package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's plans, and makes their claims. */
@Service
public class PlanService {

    private final PlanRepository plans;
    private final PersonRepository people;
    private final ClaimService claims;
    private final SheetService sheets;
    private final Audit audit;

    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims, SheetService sheets,
            Audit audit) {
        this.plans = plans;
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's plans, in the order they were added. */
    @Transactional(readOnly = true)
    public List<Plan> list(String sheetId) {
        sheets.today(sheetId);
        return plans.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a plan to a person; an amount a claim would refuse (below 0.00), an interval below 1 day, or an end
     *  before the start is refused. */
    @Transactional
    public Plan add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, int every,
            LocalDate end) {
        sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (amount.signum() < 0) {
            throw new PlanRefusedException("Enter an amount of 0.00 or more.");
        }
        if (every < 1) {
            throw new PlanRefusedException("Enter every how many days, 1 or more.");
        }
        if (end.isBefore(start)) {
            throw new PlanRefusedException("The end cannot be before the start.");
        }
        BigDecimal a = amount.setScale(2);
        Plan plan = plans.saveAndFlush(new Plan(sheetId, personId, a, start, every, end));
        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " amount=" + a.toPlainString() + " start=" + start + " every=" + every + " end=" + end);
        return plan;
    }

    /** What a generate did: the claims it made, in the order made, and the sheet's plans. */
    public record Generated(List<Claim> claims, List<Plan> plans) {
    }

    /** For every plan on the sheet in the order they were added, make a DRAFT claim of its amount with an
     *  empty note on each plan date up to its end and the sheet's today it has made none for yet; a date the
     *  claim form refuses is skipped, and tried again next time. */
    @Transactional
    public Generated generate(String sheetId, String user) {
        LocalDate today = sheets.today(sheetId);
        List<Plan> all = plans.findBySheetIdOrderByIdAsc(sheetId);
        List<Claim> made = new ArrayList<>();
        for (Plan plan : all) {
            if (people.findByIdAndSheetId(plan.getPersonId(), sheetId).isEmpty()) {
                continue; // the person is no longer on the sheet
            }
            for (LocalDate date : plan.datesDue(today)) {
                claims.addIfAccepted(sheetId, user, plan.getPersonId(), plan.getAmount(), date, "")
                        .ifPresent(claim -> {
                            made.add(claim);
                            plan.generated(date);
                        });
            }
            plans.saveAndFlush(plan);
        }
        return new Generated(made, all);
    }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Claim, Claims } from './claims';
import { Session, isDate } from './session';

/** A person's plan: a DRAFT claim of its amount on every plan date (the start, then every so many days) up to
 *  its end, and how many claims it has made so far. */
export interface Plan {
  id: number;
  personId: number;
  amount: string;
  start: string;
  every: number;
  end: string;
  generated: number;
}

/** A plan's fields as typed. */
export interface PlanFields {
  amount: string;
  start: string;
  every: string;
  end: string;
}

// The active sheet's plans, in the order they were added, re-read from the server each time the sheet is
// loaded.
@Injectable({ providedIn: 'root' })
export class Plans {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  private readonly claims = inject(Claims);

  readonly plans = signal<Plan[]>([]);
  private loads = 0;

  /** Re-read the active sheet's plans from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.plans.set([]);
    if (!user || !sid) return null;
    try {
      const plans = await firstValueFrom(this.http.get<Plan[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads) this.plans.set(plans);
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load plans (${e.status}).` : 'Could not load plans.';
    }
  }

  /** Add a plan to a person; an error message when refused (a bad amount or interval, or an end before the
   *  start). */
  async add(personId: number, f: PlanFields): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return 'Load a sheet first.';
    const amount = f.amount.trim();
    const start = f.start.trim() || (this.session.today() ?? '');
    const every = f.every.trim();
    const end = f.end.trim();
    if (!/^\d+(\.\d{1,2})?$/.test(amount)) return 'Enter an amount of 0.00 or more with up to two decimals.';
    if (!isDate(start)) return 'Enter a start date as YYYY-MM-DD.';
    if (!/^\d+$/.test(every) || Number(every) < 1) return 'Enter every how many days, 1 or more.';
    if (!isDate(end)) return 'Enter an end date as YYYY-MM-DD.';
    if (end < start) return 'The end cannot be before the start.';
    try {
      const plan = await firstValueFrom(
        this.http.post<Plan>(
          `/api/sheets/${encodeURIComponent(sid)}/people/${personId}/plans`,
          { amount, start, every: Number(every), end },
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) this.plans.update((ps) => [...ps, plan]);
      return null;
    } catch (e) {
      return failed('add plan', e);
    }
  }

  /** Make the plans' claims due by the sheet's today: how many were made, or an error message when refused. */
  async generate(): Promise<number | string> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const done = await firstValueFrom(
        this.http.post<{ made: number; claims: Claim[]; plans: Plan[] }>(
          `${this.url(sid)}/generate`,
          {},
          { headers: { 'X-User': user } },
        ),
      );
      if (this.session.sheetId() === sid) {
        this.claims.claims.update((cs) => [...[...done.claims].reverse(), ...cs]);
        this.plans.set(done.plans);
      }
      return done.made;
    } catch (e) {
      return failed('generate plans', e);
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/plans`;
  }
}

function failed(what: string, e: unknown): string {
  if (e instanceof HttpErrorResponse) {
    const err: unknown = e.error;
    if (err && typeof err === 'object' && 'message' in err && typeof err.message === 'string' && err.message) {
      return err.message;
    }
    if (e.status === 400) return 'Enter an amount with up to two decimals, dates as YYYY-MM-DD and every 1 or more days.';
    return `Could not ${what} (${e.status}).`;
  }
  return `Could not ${what}.`;
}
